import re
m=open('build/memo_full.md').read()
heads=set(re.findall(r'^### Section (\d+\.\d+)', open('build/mortgage_full.md').read(), flags=re.M))
refs=re.findall(r'Sections? (\d+\.\d+)', m)
bad=sorted(set(r for r in refs if r not in heads))
print("memo refs not matching a mortgage heading:", bad)
for b in bad:
    for line in m.split('\n'):
        if re.search(r'Sections? '+re.escape(b)+r'\b', line):
            print(' ', b, '->', line[:160])
PY"}

